export function getPostBySlug(slug: string): BlogPost | undefined {
  return BLOG_POSTS.find((p) => p.slug === slug)
}

export function getRelatedPosts(current: BlogPost, count = 3): BlogPost[] {
  const clusters = CONTENT_CLUSTERS.filter((cluster) => cluster.slugs.includes(current.slug))
  const rank = (post: BlogPost) => clusters.reduce((score, cluster) =>
    score + (cluster.slugs.includes(post.slug) ? 2 : 0) + (cluster.pillar === post.slug ? 3 : 0), 0)
  return BLOG_POSTS
    .filter((p) => p.slug !== current.slug && (rank(p) > 0 || p.category === current.category))
    .sort((a, b) => rank(b) - rank(a) || b.date.localeCompare(a.date))
    .slice(0, count)
}

